mapper.insert:
INSERT INTO games.garden_inventory (family_id, item_code, item_type, qty)
VALUES (#{familyId}, #{itemCode}, #{itemType}, #{qty})
ON DUPLICATE KEY UPDATE qty = qty + #{qty}

mapper.update:
UPDATE games.garden_inventory
SET qty = qty - #{qty}
WHERE family_id = #{familyId}
  AND item_code = #{itemCode}
  AND qty >= #{qty}

mapper.delete:
DELETE FROM games.garden_inventory
WHERE family_id = #{familyId}
  AND item_code = #{itemCode}
  AND qty <= 0
